# Generated by using Rcpp::compileAttributes(); runtime guards are maintained
# here because these wrappers define the installed package ABI contract.

.condition_runtime_state <- new.env(parent = emptyenv())
.condition_runtime_state$product_fallback_warned <- FALSE

.condition_fit_multitask_path_cpp <- function(X_list, y_list, lambda, alpha, condition_mix, condition_weight, coefficient_mask, max_iter, tol_objective, tol_coef, keep_history) {
    .Call(`_Pando_condition_fit_multitask_path_cpp`, X_list, y_list, lambda, alpha, condition_mix, condition_weight, coefficient_mask, max_iter, tol_objective, tol_coef, keep_history)
}

.condition_product_matrix_r <- function(left_matrix, right_matrix, left_index, right_index) {
    left_matrix <- methods::as(left_matrix, "dgCMatrix")
    right_matrix <- methods::as(right_matrix, "dgCMatrix")
    left_index <- as.integer(left_index)
    right_index <- as.integer(right_index)
    if (nrow(left_matrix) != nrow(right_matrix) ||
        length(left_index) != length(right_index)) {
        stop("Input dimensions are not aligned.", call. = FALSE)
    }
    if (anyNA(left_index) || anyNA(right_index) ||
        any(left_index < 1L | left_index > ncol(left_matrix)) ||
        any(right_index < 1L | right_index > ncol(right_matrix))) {
        stop("Column index is out of range.", call. = FALSE)
    }
    answer <- left_matrix[, left_index, drop = FALSE] *
        right_matrix[, right_index, drop = FALSE]
    methods::as(answer, "dgCMatrix")
}

.condition_product_matrix_cpp <- function(left_matrix, right_matrix, left_index, right_index) {
    backend <- getOption("Pando.condition_product", "auto")
    backend <- match.arg(backend, c("auto", "cpp", "R"))
    if (identical(backend, "R")) {
        return(.condition_product_matrix_r(
            left_matrix, right_matrix, left_index, right_index
        ))
    }
    native_available <- is.loaded(
        "_Pando_condition_product_matrix_cpp", PACKAGE = "Pando"
    )
    if (!native_available) {
        if (identical(backend, "cpp")) {
            stop(
                "The installed Pando native product kernel is not registered.",
                call. = FALSE
            )
        }
        if (!isTRUE(.condition_runtime_state$product_fallback_warned)) {
            warning(
                "Pando native product kernel is unavailable; using the exact sparse R fallback.",
                call. = FALSE
            )
            .condition_runtime_state$product_fallback_warned <- TRUE
        }
        return(.condition_product_matrix_r(
            left_matrix, right_matrix, left_index, right_index
        ))
    }
    tryCatch(
        .Call(
            `_Pando_condition_product_matrix_cpp`,
            left_matrix, right_matrix, left_index, right_index
        ),
        error = function(error) {
            if (identical(backend, "cpp")) stop(error)
            if (!isTRUE(.condition_runtime_state$product_fallback_warned)) {
                warning(
                    "Pando native product kernel failed (",
                    conditionMessage(error),
                    "); using the exact sparse R fallback.",
                    call. = FALSE
                )
                .condition_runtime_state$product_fallback_warned <- TRUE
            }
            .condition_product_matrix_r(
                left_matrix, right_matrix, left_index, right_index
            )
        }
    )
}
